solutionCode:
const BONUS: i32 = 5;

pub fn pontos_com_bonus(pontos: i32) -> i32 {
    pontos + BONUS
}

testsCode:
use desafio::pontos_com_bonus;

#[test]
fn testa_os_pontos_de_noventa_e_cinco_com_bonus() {
    assert_eq!(pontos_com_bonus(95), 100);
}

#[test]
fn testa_os_pontos_de_zero_com_bonus() {
    assert_eq!(pontos_com_bonus(0), 5);
}
